void CSwordOfStrength::Main()
{
 SetPredicate(NScript::CIsThingAlive(Me));
 Game->EntitySetAsOpinionSource(Me, "OPINION_SOURCE_SWORD_IN_THE_STONE");
 ParentClass->CrowdSwordPullActive = false;
 ParentClass->CrowdMemberPullingCurrent.PImp = ParentClass->CrowdMemberPullingNull.PImp;
 while (!IsActiveThreadTerminating()) {
  if (Me.MsgIsUsedBy("SCRIPT_NAME_HERO") && !ParentClass->Cutscene) {
   if (IsActiveThreadTerminating()) return;
   if (ParentClass->CrowdPulling) {
    if (IsActiveThreadTerminating()) return;
    std::vector<CScriptThing, std::allocator<CScriptThing> > crowd;
    CScriptThing thing;
    long count = Game->GetAllThingsWithScriptName("SwordCrowd", crowd);
    if (count > 1) {
     if (IsActiveThreadTerminating()) return;
     for (long i = 0; i < count; ++i) {
      thing = crowd[i];
      if (thing.IsAlive() && thing != ParentClass->CrowdMemberPullingCurrent) {
       if (IsActiveThreadTerminating()) return;
       break;
      }
     }
    }
    if (thing.IsAlive()) {
     if (IsActiveThreadTerminating()) return;
     long conversation = Game->AddNewConversation(thing, false, false);
     Game->AddPersonToConversation(conversation, Game->GetHero());
     Game->AddLineToConversation(conversation, "TEXT_QST_062_WAIT", false, thing, Game->GetHero());
    }
   } else {
    if (IsActiveThreadTerminating()) return;
    ParentClass->Cutscene = true;
   }
  }
  Game->NewScriptFrame();
 }
}

